  $('start-roads').onclick=()=>{if(validateSave(E.store.get(SAVE)))this.showModal('Start on the Lantern Roads','Begin after Chapter 01?',`<p>This starts a new journey at Level 2 with the Hollow Bell chapter complete. Your current save will be replaced.</p>`,[{text:'Keep current journey',action:'close'},{text:'Start the Lantern Roads',action:'new-campaign',primary:true}],'small');else this.newCampaign();};
  $('begin').onclick=()=>{if(validateSave(E.store.get(SAVE)))this.showModal('New journey','Start again?',`<p>Your current chapter save will be replaced when the new journey starts.</p>`,[{text:'Keep current save',action:'close'},{text:'Start new journey',action:'new',primary:true}],'small');else this.newGame();};
  $('continue').onclick=()=>this.resume();$('next-line').onclick=()=>this.nextLine();$('skip-scene').onclick=()=>this.finishDialogue();$('elsewhere').onclick=()=>this.elsewhere();$('sound').onclick=()=>{this.options.muted=!this.options.muted;this.applyOptions();};$('interact').onclick=()=>{const n=this.world.near();if(n)this.interact(n.id);};$('battle-wait').onclick=()=>{this.options.wait=!this.options.wait;this.applyOptions();this.renderBattle(true);};
  document.addEventListener('click',e=>{let b=e.target.closest?.('[data-open]');if(b){this.openMenu(b.dataset.open);return;}b=e.target.closest?.('[data-modal-action]');if(b)this.modalAction(b.dataset.modalAction,b);});
